export { sha256, sha512 } from "./hash";
export { hmacSha256, hmacVerify } from "./hmac";
export {
  randomBytes,
  randomHex,
  randomToken,
  randomId,
  randomUUID,
} from "./random";
export {
  toHex,
  fromHex,
  toBase64url,
  fromBase64url,
  utf8ToBytes,
  bytesToUtf8,
} from "./encoding";

import { toHex, utf8ToBytes } from "./encoding";

/** Returns the SHA-256 digest of a UTF-8 string as a lowercase hex string. */
export async function sha256(input: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", utf8ToBytes(input));
  return toHex(new Uint8Array(digest));
}

/** Returns the SHA-512 digest of a UTF-8 string as a lowercase hex string. */
export async function sha512(input: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-512", utf8ToBytes(input));
  return toHex(new Uint8Array(digest));
}

import { toHex, fromHex, utf8ToBytes } from "./encoding";

const ALGORITHM = { name: "HMAC", hash: "SHA-256" } as const;

async function importKey(
  secret: string,
  usages: KeyUsage[],
): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    "raw",
    utf8ToBytes(secret),
    ALGORITHM,
    false,
    usages,
  );
}

/** Returns the HMAC-SHA256 signature of message under secret as a lowercase hex string. */
export async function hmacSha256(
  secret: string,
  message: string,
): Promise<string> {
  const key = await importKey(secret, ["sign"]);
  const signature = await crypto.subtle.sign("HMAC", key, utf8ToBytes(message));
  return toHex(new Uint8Array(signature));
}

/**
 * Verifies an HMAC-SHA256 signature in constant time.
 * Delegates to subtle.verify so the runtime — not userland code — provides the constant-time comparison.
 */
export async function hmacVerify(
  secret: string,
  message: string,
  signatureHex: string,
): Promise<boolean> {
  const key = await importKey(secret, ["verify"]);
  return crypto.subtle.verify(
    "HMAC",
    key,
    fromHex(signatureHex),
    utf8ToBytes(message),
  );
}

import { toHex, toBase64url } from "./encoding";

/** Returns `length` cryptographically secure random bytes. */
export function randomBytes(length: number): Uint8Array<ArrayBuffer> {
  return crypto.getRandomValues(new Uint8Array(length));
}

/** Returns `length` random bytes as a lowercase hex string. */
export function randomHex(length: number): string {
  return toHex(randomBytes(length));
}

/**
 * Returns a `length`-byte random token as a lowercase hex string.
 * Suitable for session IDs, API keys, and CSRF tokens.
 * Default length of 32 bytes produces 256 bits of entropy.
 */
export function randomToken(length = 32): string {
  return randomHex(length);
}

/**
 * Returns a URL-safe base64 (no padding) random ID.
 * Default of 16 bytes produces a 22-character string with 128 bits of entropy.
 * Suitable for short public identifiers in URLs and logs.
 */
export function randomId(length = 16): string {
  return toBase64url(randomBytes(length));
}

/** Returns a random UUID v4 using the native crypto.randomUUID() implementation. */
export function randomUUID(): string {
  return crypto.randomUUID();
}

/** Returns the lowercase hex encoding of bytes. */
export function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

/** Decodes a lowercase or uppercase hex string. Throws on odd length or non-hex characters. */
export function fromHex(hex: string): Uint8Array<ArrayBuffer> {
  if (hex.length % 2 !== 0) {
    throw new TypeError("fromHex: input length must be even");
  }
  if (hex.length > 0 && !/^[0-9a-fA-F]+$/.test(hex)) {
    throw new TypeError("fromHex: input contains non-hex characters");
  }
  const result = new Uint8Array(hex.length / 2);
  for (let i = 0; i < result.length; i++) {
    result[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return result;
}

/** Encodes bytes as URL-safe base64 with no padding characters. */
export function toBase64url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}

/** Decodes a URL-safe base64 string (padded or unpadded) to bytes. */
export function fromBase64url(s: string): Uint8Array<ArrayBuffer> {
  const padded = s.replace(/-/g, "+").replace(/_/g, "/");
  const base64 = padded + "=".repeat((4 - (padded.length % 4)) % 4);
  const binary = atob(base64);
  const result = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    result[i] = binary.charCodeAt(i);
  }
  return result;
}

/** Encodes a string to its UTF-8 byte representation. */
export function utf8ToBytes(text: string): Uint8Array<ArrayBuffer> {
  return new TextEncoder().encode(text);
}

/** Decodes UTF-8 bytes to a string. */
export function bytesToUtf8(bytes: Uint8Array): string {
  return new TextDecoder().decode(bytes);
}
